parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "Articulo": {
      "type": ["string", "null"],
      "description": "Valor literal del campo Articulo de la fila recuperada mediante buscar_en_base_de_conocimiento. null si no hay una fila aplicable."
    },
    "Respuesta": {
      "type": ["string", "null"],
      "description": "Valor literal del campo Respuesta de esa misma fila, sin modificaciones. null si no hay una fila aplicable."
    }
  },
  "required": ["Articulo", "Respuesta"],
  "additionalProperties": false
}
